// BAD:  gluing typed input into the question (never do this)
// GOOD: placeholders — question and data travel separately
db.query("SELECT * FROM users WHERE name = $1", [typedName]);

// allowlist: only these shapes get through
function validUsername(name) {
  return /^[a-z0-9_]{3,16}$/i.test(name);
}

// same input, encoded for its destination
htmlEscape(userText);    // -> into a web page
encodeURIComponent(url); // -> into a link
// -> into SQL: placeholders, not encoding

// a strict CSP header, set by your server:
// Content-Security-Policy: script-src 'self'
// translation: only run scripts from my own site. Nothing inline.

// the playbook in one function
function saveComment(text) {
  if (!validText(text)) return "Rejected";  // 1. validate (allowlist)
  db.query("INSERT INTO comments (t) VALUES ($1)", [text]); // 2. placeholders
  return escapeHtml(text);                  // 3. encode on display
}
